async () => {
  const token = JSON.parse(localStorage.getItem('auth-store')).state.token;
  const get = async (id) => {
    const r = await fetch(`/api/datasources/${id}/data-version`, { headers: { Authorization: 'Bearer ' + token } });
    return r.ok ? (await r.json()).version : r.status;
  };
  const ds = await fetch('/api/datasources', { headers: { Authorization: 'Bearer ' + token } }).then(r => r.json());
  const list = (ds.dataSources || ds || []).map(d => ({ id: d.id, name: d.name, type: d.type }));
  const v1 = await get('ds_1786620486498');
  const v2 = await get('ds_1786406744499');
  await new Promise(rs => setTimeout(rs, 5000));
  const all = document.documentElement.textContent || '';
  return { list, v1, v2, hasBadge: /检测到数据变化/.test(all) };
}

